fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK': 512}, ...), Config({'XBLOCK': 1024}, ...), ...], key=['xnumel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)
    ...
    tmp_normed = libdevice.fma(tmp_scale, tmp_shifted, tmp14)

# CORRECT: grid must use meta['XBLOCK'] to match autotune selection
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](..., xnumel)  # no XBLOCK kwarg — autotune injects it
